// Where the Temper script is, for the texts that name it. Pure. The stage names are in stages.ts.

export const CLI = 'scripts/temper'

// Where the mod's module file sits in the plugin folder: the plugin folder is its module URL with this taken off.
export const MOD_FILE = '/hooks/temper-mod/register.tsx'

// The Temper script in the plugin folder as a full path, from the module URL of the mod (<plugin> followed by
// MOD_FILE). The path is decoded FIRST and then checked, so an encoded space or quote (%20, %27) cannot reach a
// command. Any odd location gives `scripts/temper`.
export function pluginCliFrom(url: string | undefined): string {
  try {
    const here = decodeURIComponent(new URL(url ?? '').pathname)
    if (here.endsWith(MOD_FILE) && !/[\s'"`$;&|<>()\\]/.test(here)) return `${here.slice(0, -MOD_FILE.length)}/scripts/temper`
  } catch {
    // no module URL here
  }
  return CLI
}

files.hooks/temper-mod/core/commands.ts:
// The first words of `/temper:temper` that the mod answers itself: the ones that show the run or set how Temper shows
// and enforces it. Pure. Every other word goes on to the prompt based /temper:temper: a feature description starts or
// resumes a run, and a decision word (approve, back, override, accept, pause, restart and the like) makes Claude ask
// the `Temper gate` question, where the person decides with a click (ADR 0012).

export const RESERVED = ['status', 'timeline', 'help', 'report', 'mode', 'enforcement', 'pane'] as const

export type Reserved = (typeof RESERVED)[number]

export const isReserved = (w: string): w is Reserved => (RESERVED as readonly string[]).includes(w)

export type Parsed = { word: Reserved; rest: string }

// null when the first word is not one the mod answers (a feature description, a decision word, or nothing).
export function parseArgs(args: string): Parsed | null {
  const text = args.trim()
  const m = /^(\S+)\s*([\s\S]*)$/.exec(text)
  const word = (m?.[1] ?? '').toLowerCase()
  return m && isReserved(word) ? { word, rest: (m[2] ?? '').trim() } : null
}

export const NEEDS_PERSON =
  'Temper: only the user changes what Temper shows and enforces, from the prompt box. This command came from somewhere else, such as a claude -p run, the Agent SDK or Claude. ' +
  'Next: ask the user to run it.'

export const HELP = [
  'Temper subcommands (type them after /temper:temper):',
  '  status               show where the run is',
  '  timeline             list your decisions in this run',
  '  report               show the run report (with no run active, the last one kept)',
  '  pane                 open or close the Temper pane (full mode)',
  '  mode, enforcement    show or change what Temper shows and enforces',
  'You decide at every gate in the Temper gate question: Continue, Loop back, Override and continue, Save for later.',
  'Any other text after /temper:temper is a feature description. It starts or resumes a run. With no text it takes the run up again.',
].join('\n')

files.hooks/temper-mod/core/config.ts:
// The plain text userConfig fields the mod reads. userConfig declares no `options` (that
// would stop the whole plugin loading before Claude Code 2.1.271), so every value is
// validated here. The mod reads no `.claude/temper.config`: the CLI puts what it needs in view.json.

export type UiMode = 'full' | 'minimal' | 'off'

const norm = (v: string | undefined): string => (v ?? '').trim().toLowerCase()

export function parseUiMode(v: string | undefined): UiMode {
  const n = norm(v)
  return n === 'minimal' || n === 'off' || n === 'full' ? n : 'full'
}

export function parseOnOff(v: string | undefined, fallback: 'on' | 'off'): 'on' | 'off' {
  const n = norm(v)
  return n === 'on' || n === 'off' ? n : fallback
}

export const parseEnforcement =(v: string | undefined): 'on' | 'off' => parseOnOff(v, 'on')

// "build=sonnet, plan=opus" -> { build: 'sonnet', plan: 'opus' }; malformed pairs skipped.
export function parsePhaseModels(v: string | undefined): Record<string, string> {
  const out: Record<string, string> = {}
  for (const pair of (v ?? '').split(',')) {
    const m = /^\s*([A-Za-z-]+)\s*=\s*(\S+)\s*$/.exec(pair)
    if (m?.[1] && m[2]) out[m[1].toLowerCase()] = m[2]
  }
  return out
}

export const MIN_VERSION = '2.1.287'

// "2.1.288" or "2.1.280-dev.2026..." -> [2, 1, 288 or 280]; null when not a release.
export function parseVersion(v: string): [number, number, number] | null {
  const m = /^(\d+)\.(\d+)\.(\d+)/.exec(v.trim())
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null
}

// True when `v` is at least `min`. An unparseable version is not supported: the mod
// stays inert rather than guess.
export function versionAtLeast(v: string | undefined, min: string = MIN_VERSION): boolean {
  const have = parseVersion(v ?? '')
  const want = parseVersion(min)
  if (!have || !want) return false
  for (let i = 0; i < 3; i++) {
    const a = have[i] ?? 0
    const b = want[i] ?? 0
    if (a !== b) return a > b
  }
  return true
}

export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'
const EFFORTS: readonly string[] = ['low', 'medium', 'high', 'xhigh', 'max']

// "sonnet", "sonnet:high" or ":high" -> a model, an effort, or both; empty parts stay out.
export function parsePhaseModel(value: string | undefined): { model?: string; effort?: Effort } {
  const [model = '', effort = ''] = (value ?? '').split(':').map(s => s.trim())
  const out: { model?: string; effort?: Effort } = {}
  if (model) out.model = model
  if (EFFORTS.includes(effort)) out.effort = effort as Effort
  return out
}

